import { ChangeDetectionStrategy, Component, computed, inject, input, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import type { Compare } from './compare';
import { COMPARE_INSTANCE } from './compare-token';
import { CompareStyle } from './style/comparestyle';

/**
 * CompareItem is a helper component for Compare component.
 * @group Components
 */
@Component({
    selector: 'p-compare-item',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content></ng-content>`,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [{ provide: PARENT_INSTANCE, useExisting: CompareItem }],
    host: {
        '[class]': 'cx("item")',
        '[style.position]': '"absolute"',
        '[style.inset]': '"0"',
        '[style.clip-path]': 'clipPath()',
        '[attr.data-position]': 'position()',
        '[attr.data-orientation]': 'pcCompare.orientation()',
        '[attr.data-disabled]': 'pcCompare.dataDisabled()',
        '[attr.data-dragging]': 'pcCompare.dataDragging()'
    },
    hostDirectives: [Bind]
})
export class CompareItem extends BaseComponent {
    componentName = 'CompareItem';

    bindDirectiveInstance = inject(Bind, { self: true });

    pcCompare = inject<Compare>(COMPARE_INSTANCE);

    _componentStyle = inject(CompareStyle);

    /**
     * Position of the item.
     * @group Props
     */
    position = input<'before' | 'after'>('before');

    clipPath = computed(() => this.pcCompare.getItemStyle(this.position()).clipPath);

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.pcCompare.ptms(['item']));
    }
}
